// SkillsPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import * as d3 from 'd3';
import skillsData from '../data/Skills';

// These hex values are only used by D3's SVG attribute API,
// which can't resolve CSS variables. If you change the brand
// color in GlobalStyle.css, update these to match.
const D3_COLORS = {
  border:      '#334155',
  purple:      '#8b5cf6',
  blue:        '#60a5fa',
  textPrimary: '#ffffff',
};

const categories = [
  { name: 'Frontend',             color: '#8b5cf6' },
  { name: 'Backend',              color: '#60a5fa' },
  { name: 'Database',             color: '#a78bfa' },
  { name: 'DevOps',               color: '#34d399' },
  { name: 'Cloud',                color: '#38bdf8' },
  { name: 'Cybersecurity',        color: '#f87171' },
  { name: 'Systems',              color: '#94a3b8' },
  { name: 'Software Engineering', color: '#facc15' },
  { name: 'Tools',                color: '#fbbf24' },
  { name: 'Project Management',   color: '#a3e635' },
  { name: 'Soft Skills',          color: '#fb7185' },
  { name: 'Languages',            color: '#818cf8' },
];

export default function SkillsPage() {
  const [selectedSkill, setSelectedSkill]           = useState(null);
  const [selectedCategory, setSelectedCategory]     = useState(null);
  const [highlightedConnections, setHighlightedConnections] = useState(new Set());
  const svgRef = useRef();

  const categoryGroups = {};
  skillsData.forEach(skill => {
    if (!categoryGroups[skill.category]) categoryGroups[skill.category] = [];
    categoryGroups[skill.category].push(skill);
  });

  const getDisplayedSkills = () => {
    if (selectedSkill)    return [selectedSkill];
    if (selectedCategory) return categoryGroups[selectedCategory] || [];
    return skillsData;
  };

  const displayedSkills = getDisplayedSkills();

  // D3 network graph
  useEffect(() => {
    if (!svgRef.current) return;
    const width  = svgRef.current.clientWidth;
    const height = 600;

    const nodes = [
      { id: 'Hubert', label: 'Hubert', type: 'center', category: 'center' },
      ...skillsData.map(skill => ({
        id:       skill.id,
        label:    skill.name,
        type:     'skill',
        category: skill.category,
      })),
    ];

    const links = [];
    skillsData.forEach(skill => {
      links.push({ source: 'Hubert', target: skill.id });
      skill.connections.forEach(conn => {
        if (skillsData.find(s => s.id === conn)) {
          links.push({ source: skill.id, target: conn });
        }
      });
    });

    const uniqueLinks = [];
    const linkSet = new Set();
    links.forEach(link => {
      const key = [link.source, link.target].sort().join('-');
      if (!linkSet.has(key)) { uniqueLinks.push(link); linkSet.add(key); }
    });

    const simulation = d3
      .forceSimulation(nodes)
      .force('link',      d3.forceLink(uniqueLinks).id(d => d.id).distance(80))
      .force('charge',    d3.forceManyBody().strength(-300))
      .force('center',    d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(40));

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const g = svg
      .attr('width', width)
      .attr('height', height)
      .attr('viewBox', `0 0 ${width} ${height}`)
      .append('g');

    const link = g
      .selectAll('line')
      .data(uniqueLinks)
      .enter()
      .append('line')
      .attr('stroke', D3_COLORS.border)
      .attr('stroke-width', 2)
      .attr('opacity', 0.4);

    const node = g
      .selectAll('g.node')
      .data(nodes)
      .enter()
      .append('g')
      .attr('class', 'node')
      .call(
        d3.drag()
          .on('start', (e, d) => { if (!e.active) simulation.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
          .on('drag',  (e, d) => { d.fx = e.x; d.fy = e.y; })
          .on('end',   (e, d) => { if (!e.active) simulation.alphaTarget(0); d.fx = null; d.fy = null; })
      );

    node
      .append('circle')
      .attr('r', d => (d.type === 'center' ? 40 : 25))
      .attr('fill', d => {
        if (d.type === 'center') return D3_COLORS.purple;
        const cat = categories.find(c => c.name === d.category);
        return cat ? cat.color : D3_COLORS.blue;
      })
      .attr('opacity', 0.9)
      .attr('stroke', D3_COLORS.textPrimary)
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .on('click', (e, d) => {
        if (d.type !== 'center') {
          const skill = skillsData.find(s => s.id === d.id);
          setSelectedSkill(skill);
          setSelectedCategory(null);
          setHighlightedConnections(new Set([d.id, ...skill.connections]));
        }
      })
      .on('mouseover', (e, d) => {
        link.attr('stroke', l =>
          (l.source.id === d.id || l.target.id === d.id) ? D3_COLORS.purple : D3_COLORS.border
        );
      })
      .on('mouseout', () => {
        link.attr('stroke', D3_COLORS.border);
      });

    node
      .append('text')
      .text(d => d.label)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.3em')
      .attr('fill', D3_COLORS.textPrimary)
      .attr('font-size', '12px')
      .attr('font-weight', 'bold')
      .attr('pointer-events', 'none');

    simulation.on('tick', () => {
      link
        .attr('x1', d => d.source.x)
        .attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x)
        .attr('y2', d => d.target.y);
      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    return () => simulation.stop();
  }, []);

  const handleCategoryClick = (categoryName) => {
    setSelectedCategory(selectedCategory === categoryName ? null : categoryName);
    setSelectedSkill(null);
  };

  const handleClearFilters = () => {
    setSelectedSkill(null);
    setSelectedCategory(null);
    setHighlightedConnections(new Set());
  };

  return (
    <div className="skills-container">
      {/* Hero */}
      <section className="hero-section">
        <h1 className="hero-title">My Skills & Expertise</h1>
        <p className="introduction">
          I learn best by building. Each of these skills comes from solving a problem, exploring an idea,
          or collaborating on something meaningful. My journey spans from cybersecurity fundamentals to
          full-stack web development, always driven by curiosity and real-world application.
        </p>
      </section>

      {/* Category filter */}
      <section className="category-section">
        <h2 className="section-title">Skill Categories</h2>
        <div className="category-grid">
          {categories.map(cat => {
            const skillCount = skillsData.filter(s => s.category === cat.name).length;
            const isActive   = selectedCategory === cat.name;
            return (
              <div
                key={cat.name}
                className={`category-card ${isActive ? 'active' : ''}`}
                onClick={() => handleCategoryClick(cat.name)}
              >
                <div className="category-dot" style={{ backgroundColor: cat.color }} />
                <h3 className="category-name">{cat.name}</h3>
                <p className="skill-count">{skillCount} skills</p>
              </div>
            );
          })}
        </div>

        {(selectedSkill || selectedCategory) && (
          <div className="filter-info">
            <p className="filter-text">
              {selectedSkill
                ? `Showing: ${selectedSkill.name}`
                : `Showing ${displayedSkills.length} skill(s) from ${selectedCategory}`}
            </p>
            <button onClick={handleClearFilters} className="clear-button">
              Clear Filters
            </button>
          </div>
        )}
      </section>

      {/* Network graph */}
      <section className="network-section">
        <h2 className="section-title">Skills Network Map</h2>
        <p className="network-description">
          Interactive map of how my skills connect and relate. Click on any skill bubble to highlight its connections.
        </p>
        <div className="network-container">
          <svg ref={svgRef} />
        </div>
        <div className="network-legend">
          <p className="legend-title">Click on any skill to explore its connections. Drag to reposition.</p>
          {selectedSkill && (
            <div className="selected-skill-info">
              <strong>Selected: {selectedSkill.name}</strong>
              <p>
                Connections:{' '}
                {selectedSkill.connections
                  .map(id => skillsData.find(s => s.id === id)?.name)
                  .filter(Boolean)
                  .join(', ') || 'None'}
              </p>
            </div>
          )}
        </div>
      </section>

      {/* Skill cards */}
      <section className="skills-section">
        <h2 className="section-title">
          {selectedSkill
            ? selectedSkill.name
            : selectedCategory
            ? `${selectedCategory} Skills`
            : 'Detailed Skills'}
        </h2>
        <div className="skills-grid">
          {displayedSkills.map(skill => (
            <div
              key={skill.id}
              className={`skill-card ${selectedSkill?.id === skill.id ? 'active' : ''}`}
              onClick={() => {
                setSelectedSkill(skill);
                setSelectedCategory(null);
                setHighlightedConnections(new Set([skill.id, ...skill.connections]));
              }}
            >
              <div className="skill-card-header">
                <div
                  className="category-badge"
                  style={{ backgroundColor: categories.find(c => c.name === skill.category)?.color || '#60a5fa' }}
                >
                  {skill.category}
                </div>
                <span className="learned-date">{skill.learned}</span>
              </div>

              <h3 className="skill-name">{skill.name}</h3>

              {skill.connections.length > 0 && (
                <div className="connections-container">
                  <p className="skill-label">Related Skills:</p>
                  <div className="connections-tags">
                    {skill.connections.map(connId => {
                      const connSkill = skillsData.find(s => s.id === connId);
                      return (
                        <span key={connId} className="connection-tag">
                          {connSkill?.name}
                        </span>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
